import{_ as i}from"./chunks/CityLink.vue_vue_type_script_setup_true_lang.DYs3D5sh.js";import{C as l,o as r,c as o,j as e,a,F as d,B as m,b as g,E as _,a5 as c}from"./chunks/framework.CnBNXlt7.js";import"./chunks/travelogue.BgrUIWBQ.js";import"./chunks/utils.Crj2JTAd.js";import"./chunks/dayjs.min.DTWwpTri.js";const u={id:"_2025-04-04",tabindex:"-1"},P=JSON.parse('{"title":"嘉兴","description":"","frontmatter":{"city":["嘉兴"],"date":"2025/04/04"},"headers":[],"relativePath":"trip/travelogue/20250404.md","filePath":"trip/travelogue/20250404.md","lastUpdated":1746002689000}'),b={name:"trip/travelogue/20250404.md"},V=Object.assign(b,{setup(f){return(s,t)=>{const n=l("Badge");return r(),o("div",null,[t[3]||(t[3]=e("h1",{id:"嘉兴",tabindex:"-1"},[a("嘉兴 "),e("a",{class:"header-anchor",href:"#嘉兴","aria-label":'Permalink to "嘉兴"'},"​")],-1)),(r(!0),o(d,null,m(s.$frontmatter.city,(p,k)=>(r(),g(i,{city:p,date:new Date(s.$frontmatter.date)},null,8,["city","date"]))),256)),e("h2",u,[t[0]||(t[0]=a("2025/04/04 ",-1)),_(n,{type:"warning",text:"单日速通"}),t[1]||(t[1]=a()),t[2]||(t[2]=e("a",{class:"header-anchor",href:"#_2025-04-04","aria-label":'Permalink to "2025/04/04 <Badge type="warning" text="单日速通" />"'},"​",-1))]),t[4]||(t[4]=c('<div class="tip custom-block"><p class="custom-block-title">计划</p><p>G7560 15:29-15:52 杭州东-嘉兴南 23m ￥41<br> K739 21:00-22:12 嘉兴-杭州南 1h12m ￥16.5</p></div><p>楼下公交车还要一段时间，骑自行车去地铁站。</p><p>准时抵达<strong>嘉兴南</strong>后，立即坐上电车，前往市区。这电车也太慢了，还等红绿灯。到市区竟然要近一个小时。16:45左右抵达目的地，太饿了，先去觅食吧。从瓶山出发，一路向北，沿路的建筑风格很西式。也路过了很多小吃街，看了看觉得一般，提前在美团排号。继续向北前往目的地。<br> 京杭运河贯通江浙，跨过<strong>荷月桥</strong>，抵达<strong>月河历史街区</strong>。两个酒楼，排号的酒楼(禾城陆稿荐酒楼)从来时就预计等待30分钟，到店门口还是30分钟，完全没有进度。转而去了对门的<strong>北丽桥</strong>酒楼，人也挺多的，一楼满座，被安排去了二楼包间。</p><details class="details custom-block"><summary>菜单</summary><p>剁椒皮蛋豆腐，19，皮蛋就一个，全是豆腐，好吃但皮蛋太少<br> 养生黄金米，19一位，炸米+蛤蜊，一般般<br> 酥不腻烤肉(6块)，69，好吃太少<br> 时令三鲜，59，小虾、绿蚕豆、笋混炒，凑合吃<br> 鸡枞菌爽肉，69，全是菌，菌还没洗干净，离谱<br> 韭香石锅豆面，39，就是粉丝，好吃但上菜太慢</p></details><p>景区的菜一言难尽，只能说凑合吃。吃完天色渐暗，夜景不错，简单逛逛月河街区。有个专卖招财猫的店，55元2个小招财猫，感觉挺好玩，也不算贵，很想买，但还是被劝住了(后面淘宝12块一个跟店里的一模一样……)。走回头路，一路南下，前往<strong>子城遗址公园</strong>。路边洋楼全部点亮，还是很好看的。</p><p>回到<strong>瓶山</strong>，太黑了，也就没深入探索。正好路对面就有一个超大的<strong>天主教堂</strong>，环绕一周，并没有看到哪里能够进去，里面声声诵经，只能在外面看看了。此处草坪很多，到处都是遛狗的，很是害怕。</p><p>环绕子城，正门走入，还是很大气的。正好清明有很多演出，路过了就顺带看看。</p><p>市中心前往嘉兴南需要一个小时左右，想着直接嘉兴站坐火车回杭州应该总体时间差不多的。</p><p>离嘉兴站很近，走路过去。不得不说，这个火车站修的未来科技感很强。并且这个绿皮车也是少有的空气清新，没有很多异味，不错的旅程。</p><p>实际的感受，应该还是火车慢了，因为是抵达杭州南，到家的地铁也坐的头皮发麻……</p>',10))])}}});export{P as __pageData,V as default};
